USE vanshika;
-- AlvionX Data Analytics Internship
-- Week 2 Practice Database: Customers + Orders
-- Portable script (CREATE TABLE + INSERT) - works in MySQL, PostgreSQL, SQLite, etc.

DROP TABLE IF EXISTS Orders;
DROP TABLE IF EXISTS Customers;

CREATE TABLE Customers (
    CustomerID   INTEGER PRIMARY KEY,
    CustomerName VARCHAR(100) NOT NULL,
    City         VARCHAR(50) NOT NULL,
    Region       VARCHAR(20) NOT NULL,
    SignupDate   DATE NOT NULL
);

CREATE TABLE Orders (
    OrderID         INTEGER PRIMARY KEY,
    CustomerID      INTEGER NOT NULL,
    OrderDate       DATE NOT NULL,
    Region          VARCHAR(20) NOT NULL,
    ProductCategory VARCHAR(50) NOT NULL,
    Quantity        INTEGER NOT NULL,
    Amount          INTEGER NOT NULL,
    FOREIGN KEY (CustomerID) REFERENCES Customers(CustomerID)
);
-- NOTE: Region is denormalized onto Orders (copied from the customer's
-- region) so Week 2 Session 1-2 single-table exercises do not require a
-- JOIN. Session 3 introduces JOIN using Customers.Region directly.

